"""Knowledge-graph extraction: corpus → the curated draft at `kg_autogenerated_path`.

`KnowledgeGraphBuilder` is the whole public surface, and it is a facade over three phase
modules that hand each other plain dicts in memory:

    extraction.run(corpus) → staging
    cleaning.run(staging)  → cleaned
    curation.run(cleaned)  → curated: the artifact, and its cached derivations

**A build writes exactly one ARTIFACT**, at `kg_autogenerated_path`, plus one derivation in
`cache/`: the corpus anchoring at `concept_sources_path`. It is not an artifact — it is
regenerated by a build and the curated graph is hand-edited — so it does not count as going
back to the chain of intermediate stages that was removed. The old chaining
(`knowledge_graph_partial.json` → `_cleaned.json`) stays out, along with the paths that
read it: intermediate files are not reintroduced as "checkpoints", because a build is
~15 min and repeating it was judged cheaper than the machinery.

The three phases stay separately callable, but on DATA, not on a path — `clean(staging)`,
`curate(cleaned)` — which is also what lets each of them be exercised with recorded model
answers instead of a GPU.
"""

from pathlib import Path

from loguru import logger

from ... import config
from ...core import progress
from ...core.inference import ensure_models
from ...core.workspace import Workspace
from ...instance.relations import RelationSchema
from .. import _context, _source_docs
from . import blocks, cleaning, curation, extraction, parsing, schemas

__all__ = [
    "BUILD_MODELS",
    "BUILD_PHASES",
    "KnowledgeGraphBuilder",
    "blocks",
    "cleaning",
    "curation",
    "extraction",
    "parsing",
    "schemas",
]

# Shares of a whole build, taken from a timed run rather than from how the code looks. The
# previous numbers guessed extraction at 48 % because it is the only per-chunk phase; it
# measured 8 %, while the handful of calls that reason over the whole inventory — linking,
# merging — are where the build actually spends its hour. Typing the relations is
# deterministic and takes milliseconds, so it only carries a weight to avoid a bar that
# jumps. Conversion keeps a real share for the first build and simply flies past on later
# ones, where the markdown cache answers instead of Docling. Taggability moved out of the
# build entirely (see `variant_generator/taggability.py`) and carries no weight here.
# Extraction's 8 is the measured share of ONE reading per chunk; the gleaning pass
# (`KG_EXTRACT_GLEANING_PASSES`) reads each chunk a second time with the same model and a
# slightly longer prompt, so its weight is that measurement doubled, not a new timing.
BUILD_PHASES = (
    ("convert", "Convirtiendo los documentos del corpus", 11),
    ("extract", "Extrayendo conceptos y relaciones", 16),
    ("clean", "Fusionando duplicados y normalizando nombres", 25),
    ("domains", "Agrupando los conceptos en dominios", 9),
    ("link", "Enlazando conceptos y ordenando el temario", 26),
    ("curate", "Tipando las relaciones y rompiendo ciclos", 1),
    # One call, like `curate`: it carries a weight so the bar does not jump at the end, not
    # because it costs. It goes last because it needs the names of the blocks, which is what
    # the graph knows about the subject and no earlier phase has yet.
    ("context", "Poniendo por escrito de qué asignatura es esto", 1),
)

BUILD_MODELS = [
    config.KG_EXTRACT_MODEL,
    config.EMBEDDING_LLM,
    config.KG_CLEAN_MERGE_MODEL,
    config.KG_CLEAN_DROP_MODEL,
    config.KG_DOMAINS_MODEL,
    config.KG_DOMAINS_LEFTOVERS_MODEL,
    config.KG_LINK_DOMAIN_MODEL,
    config.KG_LINK_CROSS_DOMAIN_MODEL,
    config.KG_CONTEXT_MODEL,
    config.REPAIR_LLM,
]


class KnowledgeGraphBuilder:
    def __init__(
        self,
        workspace: Workspace,
        schema: RelationSchema | None = None,
        verbose: bool = True,
    ):
        self.workspace = workspace
        self.schema = schema or config.RELATION_SCHEMA
        self.max_repair_attempts = config.MAX_JSON_REPAIR_TRIES
        self.chunk_size = config.KG_BUILDER_CHUNK_SIZE

        logger.enable(__name__) if verbose else logger.disable(__name__)

        self._converter = None

    # Docling is built on first use and never at import: the runtime pipeline does not
    # install the `builders` extra, and a converter costs ~540 MB of imports.
    @property
    def converter(self):
        if self._converter is None:
            # Lecture PDFs do not need Docling's table model, and it is slow over a whole
            # corpus; the bank and profile builders keep the default, since exercise
            # documents do carry tables.
            self._converter = _source_docs.default_converter(table_structure=False)
        return self._converter

    # PUBLIC API ----------------------------------------------------------------------------------

    def bootstrap(self) -> None:
        ensure_models(BUILD_MODELS, "del grafo de conocimiento")

    def build(self, input_dir: str | Path) -> dict:
        self.bootstrap()

        staging = self.extract(input_dir)
        if not staging:
            raise RuntimeError(f"No knowledge graph could be extracted from: {input_dir}")

        progress.checkpoint()
        cleaned = self.clean(staging)

        progress.checkpoint()
        graph = self.curate(cleaned)

        # After `curate` and not inside it: `curate(cleaned)` is separately callable and
        # promises to be a transform from data to data, while this writes a second file.
        progress.checkpoint()
        self.synthesize_context(graph)
        return graph

    # What the graph knows about the subject that nothing else does: the names of the
    # blocks the syllabus is divided into, and how big it is. NOT the concepts themselves
    # -- the prompt forbids enumerating them, and the graph is right there for whoever
    # wants the list.
    def synthesize_context(self, graph: dict) -> None:
        progress.phase("context")
        domains = list(graph.get("concepts_by_domains") or {})
        if not domains:
            return
        total = sum(len(members) for members in graph["concepts_by_domains"].values())
        evidence = "\n".join(
            [
                f"El temario se divide en {len(domains)} bloque(s), "
                f"con {total} concepto(s) en total. Se llaman:",
                *(f"- {domain}" for domain in domains),
            ]
        )
        _context.synthesize(
            self.workspace,
            evidence,
            "EL GRAFO DEL TEMARIO",
            config.KG_CONTEXT_MODEL,
            think=config.THINK_KG_CONTEXT,
        )
        progress.advance(1.0)

    def extract(self, input_dir: str | Path, recursive: bool = False) -> dict:
        return extraction.run(
            input_dir,
            converter=self.converter,
            schema=self.schema,
            chunk_size=self.chunk_size,
            markdown_cache_dir=self.workspace.markdown_cache_dir,
            max_attempts=self.max_repair_attempts,
            recursive=recursive,
        )

    def clean(self, staging: dict) -> dict:
        return cleaning.run(
            staging, schema=self.schema, max_attempts=self.max_repair_attempts
        )

    def curate(
        self,
        cleaned: dict,
        output_path: str | Path | None = None,
        sources_path: str | Path | None = None,
    ) -> dict:
        return curation.run(
            cleaned,
            output_path or self.workspace.kg_autogenerated_path,
            sources_path or self.workspace.concept_sources_path,
            schema=self.schema,
            max_attempts=self.max_repair_attempts,
        )
